const ALL_QUESTIONS=[{"subject":"Liturgics","section":"Introduction to Liturgics","q":"The word 'Liturgy' is derived from the Greek word 'Leitourgia', which in the syllabus means:","options":["Priest plus sacrifice","People plus work","Prayer plus song","Church plus service"],"answer":1,"answer_text":"People plus work","explanation":"The syllabus derives 'liturgy' from the Greek 'Leitourgia' and explains it as 'people plus work'. This emphasizes participation by the worshipping people rather than worship being monopolized by the clergy.","syllabus_page":65,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"Which of the following is NOT listed as one of the four major elements of liturgy?","options":["Order","Ritual","Ceremony","Preaching"],"answer":3,"answer_text":"Preaching","explanation":"The four major elements given are Order, Ritual, Ceremony and Liturgical Silence. Preaching is important in worship, but it is not listed among these four elements.","syllabus_page":65,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"In liturgy, 'Order' refers mainly to:","options":["The structural framework or outline of the service","The physical movements made during worship","The prescribed words that are spoken or sung","The period of silence before the sermon"],"answer":0,"answer_text":"The structural framework or outline of the service","explanation":"Order is the structural framework or programme followed in a service. It gives the service logical movement and progression, while still allowing reasonable flexibility.","syllabus_page":65,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"What are 'rubrics' in a liturgical order?","options":["Hymns sung only by the choir","Instructions that guide the liturgist on what should be done","The prayers said by the congregation","The colours used in the church year"],"answer":1,"answer_text":"Instructions that guide the liturgist on what should be done","explanation":"Rubrics are instructions, often printed in italics, bold type or brackets. They are not meant to be read aloud; they tell the liturgist when people should stand, sit, kneel, or perform other actions.","syllabus_page":66,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"Which statement best describes 'ceremony' in liturgy?","options":["It is the theological meaning of a sermon","It is the physical action necessary for public worship","It is the fixed wording of a prayer","It is the silence observed after worship"],"answer":1,"answer_text":"It is the physical action necessary for public worship","explanation":"Ceremony refers to physical actions in worship, such as standing, sitting, kneeling, processions and other bodily actions connected with the service.","syllabus_page":66,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"According to the syllabus, one important purpose of liturgical silence is to:","options":["Give the choir time to prepare","Allow worshippers to listen to what God has to say","Make the service shorter","Replace the reading of Scripture"],"answer":1,"answer_text":"Allow worshippers to listen to what God has to say","explanation":"Liturgical silence is treated as a positive act of worship. After speaking to God in prayer and praise, silence creates space for worshippers to listen and attend to God.","syllabus_page":67,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"The Old English root 'weorthscipe', from which 'worship' is derived, points to:","options":["Worthiness and giving recognition to God's worth","Singing loudly in church","Serving only through physical labour","Offering money during worship"],"answer":0,"answer_text":"Worthiness and giving recognition to God's worth","explanation":"The syllabus explains worship as attributing worth, honour and reverence to God. 'Weorthscipe' carries the idea of worthiness or worth-ship.","syllabus_page":69,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"Which two words are described as central to the definition of Christian worship?","options":["Prayer and preaching","Revelation and response","Praise and thanksgiving","Sacrifice and service"],"answer":1,"answer_text":"Revelation and response","explanation":"Christian worship is described as God's revelation of himself in Jesus Christ and the human response to that revelation. Christ stands at the centre of both revelation and response.","syllabus_page":69,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"Which statement best expresses the syllabus distinction between worship and service?","options":["All service is worship, but not all worship is service","Worship and service mean exactly the same thing","All worship is service to God, but not all service to God is worship","Service is more important than worship"],"answer":2,"answer_text":"All worship is service to God, but not all service to God is worship","explanation":"The syllabus uses Daniel and other biblical examples to show that faithful service and worship are not identical. All worship serves God, but Christian service includes many acts of obedience beyond acts of worship.","syllabus_page":70,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"According to the syllabus, worship differs from praise because worship responds primarily to:","options":["What God has done","Who God is","What the congregation has received","The music used in church"],"answer":1,"answer_text":"Who God is","explanation":"Worship responds to God's nature, being and worth, while praise responds especially to God's deeds and what God has done.","syllabus_page":71,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"Which of the following is listed among the New Testament elements of worship?","options":["Reading Scripture","Prayer","Giving","All of the above"],"answer":3,"answer_text":"All of the above","explanation":"The syllabus lists reading Scripture, prayer, singing, preaching, celebrating Baptism and the Lord's Supper, and giving as elements of worship.","syllabus_page":72,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"In the acronym PRAISE used for the worship leader's dependence on the Holy Spirit, the letter 'R' stands for:","options":["Reverence","Reliance on the Holy Spirit","Reading Scripture","Repentance"],"answer":1,"answer_text":"Reliance on the Holy Spirit","explanation":"PRAISE includes Preparation with the Holy Spirit through Prayer, Reliance on the Holy Spirit, Adjustment, Inspiration, Singing in the Holy Spirit, and Edifying the church.","syllabus_page":72,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"A sacrament is generally described in the syllabus as:","options":["A private religious opinion","An outward and visible sign of an inward and spiritual grace","A sermon preached by an ordained minister","Any religious object kept in a church"],"answer":1,"answer_text":"An outward and visible sign of an inward and spiritual grace","explanation":"The syllabus gives the classic description of a sacrament as an outward and visible sign of an inward and spiritual grace: something visible expressing an unseen spiritual reality.","syllabus_page":74,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"The word 'sacrament' is derived from the Latin:","options":["Sacramentum","Leitourgia","Proskuneo","Koinonia"],"answer":0,"answer_text":"Sacramentum","explanation":"The syllabus traces the word sacrament to the Latin 'sacramentum'.","syllabus_page":74,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"How many sacraments are accepted and performed by Methodists according to the syllabus?","options":["Two","Five","Seven","Thirty"],"answer":0,"answer_text":"Two","explanation":"The syllabus states that Protestant churches, including Methodists, accept two sacraments: Baptism and the Eucharist or Lord's Supper.","syllabus_page":75,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"Which pair names the two sacraments accepted by Methodists?","options":["Confirmation and Ordination","Baptism and the Lord's Supper","Matrimony and Penance","Baptism and Confirmation"],"answer":1,"answer_text":"Baptism and the Lord's Supper","explanation":"Methodists recognize Baptism and the Eucharist, also called the Lord's Supper, as the two sacraments.","syllabus_page":75,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"Which of the following is one of the five elements of a sacrament listed in the syllabus?","options":["Matter","Form","Minister","All of the above"],"answer":3,"answer_text":"All of the above","explanation":"The five elements listed are Matter, Form, Minister or Officiant, the Gift and the Benefit.","syllabus_page":75,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"In the elements of a sacrament, 'Matter' refers to:","options":["The physical action and material used","The words of institution","The ordained officiant","The grace promised by God"],"answer":0,"answer_text":"The physical action and material used","explanation":"Matter is the physical action and material involved, such as water in Baptism and bread and wine in the Eucharist. The Form refers to the words used.","syllabus_page":75,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"Methodist Studies is described as the discipline dealing with the history, beliefs and practices of Methodism as:","options":["Only a political movement","A Reform Movement and a Denomination within Evangelical Christianity","A branch of Roman Catholicism","Only an English social club"],"answer":1,"answer_text":"A Reform Movement and a Denomination within Evangelical Christianity","explanation":"The syllabus defines Methodist Studies in terms of Methodism both as a reform movement and as a denomination within Evangelical Christianity.","syllabus_page":83,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"Modern Methodist groups trace their roots especially to the work of:","options":["John and Charles Wesley","Martin Luther and John Calvin","Peter and Paul","George Fox and William Penn"],"answer":0,"answer_text":"John and Charles Wesley","explanation":"The syllabus states that Methodist groups trace their roots to John and Charles Wesley, sons of Samuel and Susanna Wesley.","syllabus_page":83,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"Which group was associated with John and Charles Wesley, George Whitefield and others at Oxford?","options":["The Clapham Sect","The Holy Club","The SPCK","The Non-Aligned Movement"],"answer":1,"answer_text":"The Holy Club","explanation":"The Holy Club was associated with John and Charles Wesley and companions including George Whitefield, Benjamin Ingham, Charles Delamotte and John Clayton.","syllabus_page":83,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"One major reason given for studying Methodism is to:","options":["Forget denominational history","Know and preserve the heritage and core values of the faith community","Replace the study of Scripture","Avoid Christian formation"],"answer":1,"answer_text":"Know and preserve the heritage and core values of the faith community","explanation":"The syllabus argues that neglecting history, doctrines and core values weakens Christian formation. Methodist Studies helps Methodists know and transmit their heritage.","syllabus_page":83,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"Who were the parents of John and Charles Wesley?","options":["Samuel and Susanna Wesley","John and Mary Wesley","George and Elizabeth Whitefield","Samuel and Anne Annesley"],"answer":0,"answer_text":"Samuel and Susanna Wesley","explanation":"Samuel and Susanna Wesley were the parents of John and Charles. Their Epworth home strongly shaped the brothers' education, discipline and spirituality.","syllabus_page":84,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"How many children were born to Samuel and Susanna Wesley according to the syllabus?","options":["Nine","Twelve","Nineteen","Twenty-four"],"answer":2,"answer_text":"Nineteen","explanation":"The syllabus states that nineteen children were born to Samuel and Susanna Wesley; ten died in infancy and nine survived.","syllabus_page":85,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"The Wesleyan Methodist Missionary Society (WMMS) was formed in England in:","options":["1703","1738","1813","1835"],"answer":2,"answer_text":"1813","explanation":"The WMMS was formed in 1813 by the Wesleyan Methodist Conference and began work in Ghana in 1835.","syllabus_page":106,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"Which group provided the foundation members for the Methodist Church Ghana before the arrival of the first missionary?","options":["The Cape Coast SPCK or Bible Band","The Holy Club","The Moravian Society","The British Methodist Conference"],"answer":0,"answer_text":"The Cape Coast SPCK or Bible Band","explanation":"The Cape Coast SPCK, also known as the Meeting or Bible Band, requested Bibles and became the foundation group from which Methodist work in Ghana developed.","syllabus_page":107,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"Who carried the Cape Coast group's request to the Wesleyan Methodist Missionary Society in England?","options":["Captain Potter","Thomas Birch Freeman","George Wrigley","John Wesley"],"answer":0,"answer_text":"Captain Potter","explanation":"Captain Potter, an English sailor and Methodist, carried the request and offered to transport any missionary appointed to Cape Coast at his own expense.","syllabus_page":108,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"Who was the first Wesleyan Methodist missionary sent to Cape Coast?","options":["Thomas Birch Freeman","Joseph Rhodes Dunwell","George Wrigley","Robert Brooking"],"answer":1,"answer_text":"Joseph Rhodes Dunwell","explanation":"Joseph Rhodes Dunwell was recruited by the WMMS and arrived in Cape Coast on January 1, 1835, formally introducing Methodism in Ghana.","syllabus_page":108,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"Joseph Rhodes Dunwell arrived in Cape Coast on:","options":["January 1, 1835","June 24, 1835","September 15, 1836","January 3, 1838"],"answer":0,"answer_text":"January 1, 1835","explanation":"The syllabus dates Dunwell's arrival to January 1, 1835. He died six months later on June 24, 1835.","syllabus_page":109,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"Which missionary strongly promoted the training and use of a native ministry and opened a mission station in Kumasi?","options":["George Wrigley","Thomas Birch Freeman","Joseph Rhodes Dunwell","Peter Harrop"],"answer":1,"answer_text":"Thomas Birch Freeman","explanation":"Thomas Birch Freeman believed strongly in native ministry, trained local workers, travelled widely, and succeeded in opening a mission station in Kumasi between 1841 and 1842.","syllabus_page":112,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"In the syllabus, to 'develop' generally means to:","options":["Cause to grow larger, fuller or more mature","Reduce all social differences","Become politically independent","Increase only religious activity"],"answer":0,"answer_text":"Cause to grow larger, fuller or more mature","explanation":"The syllabus begins with the broad meaning of development as causing something to grow larger, fuller or more mature before focusing mainly on economic development.","syllabus_page":127,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"The syllabus mainly limits its discussion of development to:","options":["Economic development","Liturgical development","Biblical criticism","Church architecture"],"answer":0,"answer_text":"Economic development","explanation":"Although development can be economic, political, religious, social or technical, the section mainly studies economic development and the distinction between developed and developing countries.","syllabus_page":127,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"Developed or 'First World' countries are described mainly as:","options":["Industrialized and relatively prosperous","Nonindustrial and absolutely poor","Countries without markets","Countries without natural resources"],"answer":0,"answer_text":"Industrialized and relatively prosperous","explanation":"The syllabus describes the North as industrialized and relatively prosperous and contrasts it with the mainly nonindustrial and poorer South.","syllabus_page":127,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"Economics is described as dealing broadly with production or use of resources, distribution of wealth, and:","options":["Economic theories or ideologies","Liturgical seasons","Church sacraments","Biblical languages"],"answer":0,"answer_text":"Economic theories or ideologies","explanation":"The syllabus identifies three broad areas: management of natural resources, distribution of wealth, and economic theories or ideologies used to explain or justify these arrangements.","syllabus_page":128,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"The system of exchange in which goods or services are passed as gifts without explicit contracting for payment is called:","options":["Reciprocity","Capitalism","Social action","Industrialization"],"answer":0,"answer_text":"Reciprocity","explanation":"Reciprocity is gift-based exchange without bargaining for a specific return. The syllabus later distinguishes generalized, balanced and negative reciprocity.","syllabus_page":129,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"What is the main difference between social service and social action in the syllabus?","options":["Social service helps immediate needs, while social action addresses conditions causing the problem","Social action is only prayer, while social service is preaching","They mean exactly the same thing","Social service is political while social action is never public"],"answer":0,"answer_text":"Social service helps immediate needs, while social action addresses conditions causing the problem","explanation":"The Good Samaritan example illustrates social service by caring for the injured person. Social action would also seek to make the dangerous road safe by confronting the cause of the problem.","syllabus_page":130,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"According to the syllabus' use of Maslow's hierarchy, which needs are the basic necessities of life?","options":["Physiological needs","Esteem needs","Self-actualization needs","Social needs"],"answer":0,"answer_text":"Physiological needs","explanation":"Physiological needs include food, water, clothing, shelter and health. Failure to secure these basic necessities is treated as a key sign of poverty.","syllabus_page":131,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"Which is the highest level in Maslow's hierarchy as presented in the syllabus?","options":["Safety and security","Social needs","Self-actualization","Esteem"],"answer":2,"answer_text":"Self-actualization","explanation":"Self-actualization is the highest level, where people seek to fulfill and develop their God-given potential rather than merely secure money, status or social belonging.","syllabus_page":132,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"Paul's teaching in 1 Thessalonians 4:11-12 encourages Christians to:","options":["Avoid work and wait for help","Work with their hands and avoid unnecessary dependence","Seek prestige before basic needs","Reject all material provision"],"answer":1,"answer_text":"Work with their hands and avoid unnecessary dependence","explanation":"The syllabus uses Paul's teaching to emphasize productive work, providing for daily necessities and living responsibly rather than becoming needlessly dependent on others.","syllabus_page":132,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"Agur's prayer discussed in the syllabus is found in:","options":["Proverbs 30:7-9","Psalm 23","Matthew 6:9-13","Romans 12:1-2"],"answer":0,"answer_text":"Proverbs 30:7-9","explanation":"The syllabus uses Proverbs 30:7-9 to discuss the undesirability and spiritual dangers of poverty.","syllabus_page":132,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"According to the syllabus, Jesus' statement 'The poor you will always have with you' should NOT be understood as:","options":["An endorsement of poverty","A call to remain open-handed to the poor","A statement made in a particular context","A reminder that helping the poor remains possible"],"answer":0,"answer_text":"An endorsement of poverty","explanation":"The syllabus explicitly rejects the idea that Jesus was endorsing poverty. The statement is read alongside Deuteronomy 15:11 and the continuing responsibility to care for the poor.","syllabus_page":132,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"Which role does the syllabus assign to the Church in poverty reduction?","options":["Only giving occasional hand-outs","Providing help, teaching attitudinal change, and advocating for good policies","Avoiding economic matters","Leaving poverty entirely to government"],"answer":1,"answer_text":"Providing help, teaching attitudinal change, and advocating for good policies","explanation":"The Church is urged not only to assist the poor directly but also to teach, advocate for sound policies, and encourage attitudes and actions that help people move out of poverty.","syllabus_page":133,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"The syllabus defines work as:","options":["Only paid manual labour","Any physical or mental activity directed toward accomplishing a task, including labour by which people earn a livelihood","Only church activity","Any activity done without planning"],"answer":1,"answer_text":"Any physical or mental activity directed toward accomplishing a task, including labour by which people earn a livelihood","explanation":"Work includes physical and mental activity directed toward a task and the labour through which people earn their livelihood.","syllabus_page":133,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"According to Genesis 2:15 as used in the syllabus, one of humanity's primary tasks in Eden was to:","options":["Avoid the ground","Work the ground","Build a city","Establish a monarchy"],"answer":1,"answer_text":"Work the ground","explanation":"The syllabus presents work as part of God's intention for humanity, pointing to the command to work the ground in Eden.","syllabus_page":133,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"What problem arose among some Christians in the Thessalonian church?","options":["They worked too much","They stopped working because they expected Christ's return immediately","They refused to pray","They rejected Paul's letters"],"answer":1,"answer_text":"They stopped working because they expected Christ's return immediately","explanation":"Some Thessalonian believers treated Christ's expected return as a reason to abandon responsibilities. Paul called them back to responsible and productive work.","syllabus_page":134,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"Paul's statement 'If anyone will not work, he shall not eat' is discussed in connection with:","options":["Laziness and idleness","The sacraments","Missionary expansion","Liturgical silence"],"answer":0,"answer_text":"Laziness and idleness","explanation":"The statement addresses believers who refused productive work and became burdens on others while waiting for Christ's return.","syllabus_page":134,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"According to the syllabus, spirituality should be understood mainly in terms of:","options":["Religious activities alone","Conduct, character, and the indwelling power of the Holy Spirit, not religious activity alone","Avoiding secular work","Spending the whole day at prayer centres"],"answer":1,"answer_text":"Conduct, character, and the indwelling power of the Holy Spirit, not religious activity alone","explanation":"The syllabus argues that spirituality is more than attending services, praying and studying the Bible. It includes conduct and character shaped by the Holy Spirit.","syllabus_page":137,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"What lesson does Proverbs 6:6-11 draw from the ant?","options":["Depend on constant supervision","Practice diligence, initiative and preparation","Avoid future planning","Work only when commanded"],"answer":1,"answer_text":"Practice diligence, initiative and preparation","explanation":"The ant is presented as self-disciplined and industrious, working without a taskmaster and preparing for future need. The passage contrasts diligence with the sluggard's procrastination and poverty.","syllabus_page":137,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"Which passage is central to the syllabus discussion of humanity's responsibility to work and care for the environment?","options":["Genesis 2:15","Acts 2:42","Romans 8:1","Matthew 28:19"],"answer":0,"answer_text":"Genesis 2:15","explanation":"Genesis 2:15 is used to ground the idea that human beings have a God-given responsibility to work the earth and take care of it.","syllabus_page":139,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"Which of the following is listed as an activity that degrades the environment?","options":["Bush burning","Indiscriminate felling of trees","Fishing with poisonous chemicals","All of the above"],"answer":3,"answer_text":"All of the above","explanation":"The syllabus names bush burning, deforestation and poisonous fishing methods among destructive human activities.","syllabus_page":140,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"In the syllabus, human 'ruling' over creation includes:","options":["Care, control and supervision of creation","Unlimited destruction of natural resources","Ignoring environmental laws","Leaving all responsibility to government"],"answer":0,"answer_text":"Care, control and supervision of creation","explanation":"Ruling is interpreted as responsible control and supervision. Humans are accountable for maintaining and protecting what God has entrusted to them.","syllabus_page":141,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"Which topic is specifically included under the Christian's responsibility for the environment?","options":["Agriculture and land degradation","Water and environmental destruction","Bush fires","All of the above"],"answer":3,"answer_text":"All of the above","explanation":"The environment section treats agriculture and land degradation, water and environmental destruction, and bush fires as major areas of Christian responsibility.","syllabus_page":141,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"A bushfire is defined in the syllabus as:","options":["Any fire inside a house","A wildfire occurring in grassland, woodland or forest","Only a fire caused by lightning","Any controlled farm fire"],"answer":1,"answer_text":"A wildfire occurring in grassland, woodland or forest","explanation":"The syllabus defines a bushfire as a wildfire in the bush, including grassland, woodland or forest.","syllabus_page":146,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"Which of the following is identified as a Christian response to bushfires?","options":["Apathy when the bush is burning","Supporting prevention, fire-fighting and responsible stewardship","Starting fires to clear all vegetation","Ignoring government efforts"],"answer":1,"answer_text":"Supporting prevention, fire-fighting and responsible stewardship","explanation":"The syllabus treats environmental stewardship as a Christian responsibility and calls for prevention, support for fire control, volunteer action and rejection of apathy.","syllabus_page":147,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"The syllabus traces the word 'religion' to Latin roots conveying the idea of:","options":["That which binds together","That which separates people","Public entertainment","Economic exchange"],"answer":0,"answer_text":"That which binds together","explanation":"The syllabus derives religion from Latin roots explained as meaning 'that which binds together'.","syllabus_page":148,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"Sir Edward Burnett Tylor's definition of religion emphasized:","options":["Animism and belief in supernatural beings","Economic markets","Liturgical order","Political development"],"answer":0,"answer_text":"Animism and belief in supernatural beings","explanation":"Tylor is presented as defining religion especially through animism, belief in supernatural beings such as souls, ghosts, spirits, gods and goddesses.","syllabus_page":148,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"Robert Marett used the term 'mana' to refer to:","options":["A written creed","Impersonal spiritual power","A form of government","A Christian sacrament"],"answer":1,"answer_text":"Impersonal spiritual power","explanation":"The syllabus explains mana as an impersonal spiritual power, introduced by Marett in criticism of definitions that focused only on personal spiritual beings.","syllabus_page":148,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"In simple language, culture is described in the syllabus as:","options":["The way of life passed from one generation to the next","Only traditional clothing","Only religious belief","The laws of government"],"answer":0,"answer_text":"The way of life passed from one generation to the next","explanation":"Culture is the learned system of beliefs, feelings and rules for living around which people organize life. In simple terms, it is a way of life transmitted from generation to generation.","syllabus_page":149,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"What distinguishes a subculture from the dominant culture?","options":["A subculture belongs to a smaller segment of society with a distinctive identity while still participating in the wider culture","A subculture has no shared beliefs","A subculture exists outside society","A subculture is always religious"],"answer":0,"answer_text":"A subculture belongs to a smaller segment of society with a distinctive identity while still participating in the wider culture","explanation":"A subculture guides the distinctive identity and customs of a smaller segment of society, while its members also participate in the dominant culture of the larger society.","syllabus_page":150,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"The Aboakyer festival is used in the syllabus as an example of how shared customs can:","options":["Destroy community identity","Help people understand themselves as a community with a unique culture","Replace language","Prevent cultural continuity"],"answer":1,"answer_text":"Help people understand themselves as a community with a unique culture","explanation":"The syllabus uses Aboakyer to illustrate how participation in shared traditions gives meaning, continuity and a sense of common identity to a community.","syllabus_page":150,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"Before its specifically Christian use, the word 'liturgy' was originally applied to:","options":["Any public duty","Only priestly sacrifice","Private prayer","The singing of Psalms"],"answer":0,"answer_text":"Any public duty","explanation":"The syllabus explains that 'leitourgia' originally referred broadly to public duty. Its meaning later became associated with religious and ecclesiastical service.","syllabus_page":65,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"In the Septuagint, the term from which 'liturgy' comes was applied especially to:","options":["Service in the Temple","Military service","Family worship only","Private meditation"],"answer":0,"answer_text":"Service in the Temple","explanation":"In the Septuagint, the term was used for service in the Temple. This helps explain how a word for public service acquired a specifically religious meaning.","syllabus_page":65,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"In ecclesiastical usage, the syllabus says that 'liturgy' came to mean:","options":["The official worship of the Church","Only the sermon","Only Holy Communion","Only the work of the choir"],"answer":0,"answer_text":"The official worship of the Church","explanation":"The word came to be applied to the official worship of the Church. The syllabus notes that Eastern usage particularly associated it with the Eucharist, while Western usage could refer to the whole formal corporate worship.","syllabus_page":65,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"A good liturgy should express the common participation of:","options":["Only ordained ministers","Only the choir","Both clergy and laity","Only Local Preachers"],"answer":2,"answer_text":"Both clergy and laity","explanation":"Because liturgy is described as the 'work of the people', the syllabus stresses participation by both clergy and laity. Worship becomes deficient when the clergy monopolize it.","syllabus_page":65,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"One advantage of a familiar fixed order of worship is that it:","options":["Eliminates all flexibility","Reduces the need for repeated announcements directing the congregation","Prevents congregational participation","Makes preaching unnecessary"],"answer":1,"answer_text":"Reduces the need for repeated announcements directing the congregation","explanation":"A familiar order helps worship flow naturally without frequent announcements about what comes next. The syllabus still allows reasonable flexibility within an ordered service.","syllabus_page":65,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"In liturgy, 'ritual' refers mainly to:","options":["The form of words said or sung in worship","The architecture of the church","The movement of ministers","The silent period after a sermon"],"answer":0,"answer_text":"The form of words said or sung in worship","explanation":"Ritual is the form of words used in worship, especially prescribed words that are said or sung. These words are important channels of communication between God and worshippers.","syllabus_page":66,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"According to the syllabus, liturgical music should be judged mainly by its ability to:","options":["Display musical skill","Express Christian ideas","Keep the service long","Replace spoken prayer"],"answer":1,"answer_text":"Express Christian ideas","explanation":"Liturgical music is used for the sake of the words and the faith they express. Its fitness is therefore judged by how well it communicates Christian ideas.","syllabus_page":66,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"Which of the following can function as a visual aid in liturgical ceremony?","options":["Church architecture and furnishings","Only printed sermons","Only musical notes","Only announcements"],"answer":0,"answer_text":"Church architecture and furnishings","explanation":"The syllabus says that architecture, furnishings and ornaments can serve as visual aids by suggesting holiness, solemnity and the character of worship.","syllabus_page":67,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Introduction to Liturgics","q":"Which of the following is identified as a danger of liturgical worship?","options":["Cold formality","Congregational participation","Biblical language","A balanced church year"],"answer":0,"answer_text":"Cold formality","explanation":"The syllabus warns that liturgy can become a cold formality, a routine without love for God, or an occasion for the officiant's pride. Good liturgy therefore requires spiritually prepared leadership.","syllabus_page":68,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"The Old Testament words 'shachah' and 'kaghadh' used for worship carry the idea of:","options":["Bowing down or prostrating oneself","Teaching a lesson","Giving money","Travelling to Jerusalem"],"answer":0,"answer_text":"Bowing down or prostrating oneself","explanation":"These Old Testament terms express bodily reverence, such as bowing, prostrating or falling down before God.","syllabus_page":69,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"The New Testament word 'proskuneo' used for worship carries the idea of:","options":["Kissing toward or prostrating oneself in homage","Studying privately","Working for wages","Serving food"],"answer":0,"answer_text":"Kissing toward or prostrating oneself in homage","explanation":"The syllabus explains 'proskuneo' as to kiss toward, prostrate oneself, or render homage. It expresses reverence and submission.","syllabus_page":69,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"Which statement about Christian worship is supported by the syllabus?","options":["It is tied to one sacred place only","It may be personal or corporate and is fundamentally connected with the heart or attitude","It occurs only in a church building","It is limited to Sundays"],"answer":1,"answer_text":"It may be personal or corporate and is fundamentally connected with the heart or attitude","explanation":"The syllabus teaches that worship may be personal or corporate and is not finally tied to a particular place. The attitude of the worshipper and the relationship with God are central.","syllabus_page":69,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"Why is worship described as a dialogue?","options":["Because only the congregation speaks","Because God speaks and the people respond","Because the preacher and choir debate","Because worship is mainly conversation among members"],"answer":1,"answer_text":"Because God speaks and the people respond","explanation":"God speaks through Scripture, preaching and Christ's presence in Holy Communion, while worshippers respond with praise, prayer and the offering of themselves.","syllabus_page":69,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"The statement 'worship is a lifestyle, not an event' means that worship:","options":["Is confined to formal services","Should shape the Christian's whole daily relationship with Christ","Requires music at all times","Can happen only when a congregation gathers"],"answer":1,"answer_text":"Should shape the Christian's whole daily relationship with Christ","explanation":"The syllabus presents worship as a day-to-day relationship with Christ. Formal services matter, but worship is not limited by a building, time or single religious event.","syllabus_page":70,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"Daniel's service to Nebuchadnezzar and Darius is used to show that:","options":["Service and worship are always identical","A person may faithfully serve someone without worshipping that person","Civil service is forbidden","Only kings may be served"],"answer":1,"answer_text":"A person may faithfully serve someone without worshipping that person","explanation":"Daniel served earthly rulers faithfully but refused worship that belonged to God. The example shows why all worship is service to God, while not every form of service is worship.","syllabus_page":70,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"Praise differs from worship in that praise responds especially to:","options":["God's deeds and benefits","God's existence alone","The liturgical calendar","The authority of the minister"],"answer":0,"answer_text":"God's deeds and benefits","explanation":"The syllabus distinguishes worship as response to who God is and praise as response to what God has done, such as provision, forgiveness, protection and salvation.","syllabus_page":71,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"Which biblical figures are cited as refusing worship directed to created beings?","options":["Peter and an angel","Paul and Barnabas only","Moses and Aaron","David and Solomon"],"answer":0,"answer_text":"Peter and an angel","explanation":"Peter refused Cornelius' worship in Acts 10, and the angel in Revelation 22 refused John's worship. The syllabus uses these examples to stress that worship belongs to God alone.","syllabus_page":72,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Worship","q":"According to the syllabus, physical expressions such as clapping, dancing and lifting hands in worship should be:","options":["Completely forbidden","Practised without restraint","Used with honour, discernment and decorum","Required in every service"],"answer":2,"answer_text":"Used with honour, discernment and decorum","explanation":"The syllabus does not reject bodily expression, but warns against excess and abuse. Such expressions should honour God, fit the occasion and remain consistent with Christian worship.","syllabus_page":74,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"Which of the following is NOT given as a reason for continuing the sacramental rites?","options":["Their institution by Christ","Christ's command for their continuance","Their role as symbols of divine acts in the Gospel","Their ability to replace preaching"],"answer":3,"answer_text":"Their ability to replace preaching","explanation":"The syllabus gives three grounds for continuing the sacraments: Christ instituted them, commanded their continuance, and they function as essential symbols of divine acts in the Gospel.","syllabus_page":75,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"Hugo of Saint Victor in the twelfth century is said to have spoken of as many as:","options":["2 sacraments","7 sacraments","12 sacraments","30 sacraments"],"answer":3,"answer_text":"30 sacraments","explanation":"The syllabus notes that Hugo of Saint Victor spoke of as many as thirty sacraments before later Western teaching settled on other enumerations.","syllabus_page":75,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"Peter Lombard estimated the number of sacraments to be:","options":["Two","Five","Seven","Thirty"],"answer":2,"answer_text":"Seven","explanation":"Peter Lombard is presented as identifying seven: Baptism, Eucharist, Confirmation, Orders, Matrimony, Penance and Extreme Unction.","syllabus_page":75,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"In the five elements of a sacrament, 'Form' refers to:","options":["The words that signify the institution","The physical material used","The person receiving the sacrament","The church building"],"answer":0,"answer_text":"The words that signify the institution","explanation":"The Form is the wording of the rite, such as the words of institution at the Eucharist. It corresponds to the ritual dimension of the sacrament.","syllabus_page":75,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"According to the syllabus, the 'Minister' or officiant of the sacrament is:","options":["Any person chosen by the congregation","The ordained clergy of the Word set aside for Word and Sacrament","Only a choir leader","Any baptized adult"],"answer":1,"answer_text":"The ordained clergy of the Word set aside for Word and Sacrament","explanation":"The syllabus identifies the minister or officiant as ordained clergy set apart for the administration of Word and Sacrament.","syllabus_page":75,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"The 'Sacramental Gift' is:","options":["The money offered by the congregation","The grace promised by God to the recipient","The physical bread alone","The service book"],"answer":1,"answer_text":"The grace promised by God to the recipient","explanation":"Among the five elements, the Gift is the grace promised by God. The sacrament visibly signifies and conveys the promised spiritual blessing.","syllabus_page":75,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"The Greek word from which 'Baptism' is derived is explained as meaning:","options":["To sing","To dip or immerse in water","To preach","To anoint with oil"],"answer":1,"answer_text":"To dip or immerse in water","explanation":"The syllabus connects baptism with the Greek 'baptize', meaning to dip or immerse in water.","syllabus_page":76,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"Baptism is described in the syllabus as the central act of:","options":["Christian initiation","Church administration","Marriage preparation","Funeral worship"],"answer":0,"answer_text":"Christian initiation","explanation":"Baptism is presented as the central act of Christian initiation and is compared with circumcision in the Old Testament covenant community.","syllabus_page":76,"source_type":"Syllabus-derived likely practice question"},{"subject":"Liturgics","section":"Sacraments","q":"The 'efficacy' of a sacrament refers to:","options":["Its length","Its ability to effect the purpose for which it is administered","The number of people present","The age of the minister"],"answer":1,"answer_text":"Its ability to effect the purpose for which it is administered","explanation":"The syllabus uses efficacy to mean the sacrament's effectiveness in accomplishing what it signifies, whether understood as imparting grace or effectively representing the reality it signifies.","syllabus_page":80,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"Bartholomew Wesley was ejected from his parish after refusing to conform to the:","options":["Act of Uniformity of 1662","Toleration Act of 1689","Reform Act of 1832","Act of Emancipation"],"answer":0,"answer_text":"Act of Uniformity of 1662","explanation":"Bartholomew Wesley, John Wesley's paternal great-grandfather, was among ministers ejected for refusing conformity under the 1662 settlement.","syllabus_page":83,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"Samuel Wesley became rector at Epworth in:","options":["1662","1697","1703","1729"],"answer":1,"answer_text":"1697","explanation":"The syllabus states that Samuel Wesley, an Anglican minister and the father of John and Charles, became rector at Epworth in 1697.","syllabus_page":85,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"John Wesley was born on:","options":["June 28, 1703","May 24, 1738","December 18, 1708","June 24, 1835"],"answer":0,"answer_text":"June 28, 1703","explanation":"The syllabus gives John Benjamin Wesley's birth as June 28, 1703. He was the fifteenth child of Samuel and Susanna Wesley.","syllabus_page":86,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"Charles Wesley was born on:","options":["January 1, 1835","December 18, 1708","May 1, 1738","June 28, 1703"],"answer":1,"answer_text":"December 18, 1708","explanation":"Charles Wesley was born on December 18, 1708, five years after John. The syllabus identifies him as the seventeenth of the nineteen Wesley children.","syllabus_page":86,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"At what age did John Wesley enter Charterhouse School?","options":["Five","Eight","Eleven","Seventeen"],"answer":2,"answer_text":"Eleven","explanation":"John Wesley entered Charterhouse in 1714 at the age of eleven, on a scholarship provided by the Duke of Buckingham.","syllabus_page":88,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"John Wesley and his companions sailed for Georgia on October 21, 1735 aboard the:","options":["Simmonds","Mayflower","Victory","Endeavour"],"answer":0,"answer_text":"Simmonds","explanation":"John Wesley, Charles Wesley, Benjamin Ingham and Charles Delamotte left for Georgia aboard the Simmonds.","syllabus_page":92,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"One important lesson Wesley drew from the Moravians was that:","options":["Faith must be fearless and piety can be cheerful","Christianity requires political office","Worship should exclude hymns","Salvation depends on social status"],"answer":0,"answer_text":"Faith must be fearless and piety can be cheerful","explanation":"The Moravians impressed Wesley with their calm faith. The syllabus says they taught him, among other things, that faith must be fearless and piety can be buoyant or cheerful.","syllabus_page":93,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"John Wesley's Aldersgate Street experience occurred on:","options":["May 24, 1738","October 21, 1735","May 1, 1738","June 1744"],"answer":0,"answer_text":"May 24, 1738","explanation":"On May 24, 1738 Wesley attended a society in Aldersgate Street where Luther's preface to Romans was being read and described his heart as 'strangely warmed'.","syllabus_page":97,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Beginnings of Methodism","q":"The earliest religious society of Wesley's own in England was inaugurated, on Peter Bohler's advice, on:","options":["May 1, 1738","May 24, 1738","December 18, 1708","January 1, 1835"],"answer":0,"answer_text":"May 1, 1738","explanation":"The syllabus says Wesley's earliest society in England was inaugurated on May 1, 1738. It first met at James Hutton's house and later at Fetter Lane.","syllabus_page":100,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"The WMMS began work in Ghana in 1835, how many years after its formation in England?","options":["Ten years","Twenty-two years","Thirty years","Fifty years"],"answer":1,"answer_text":"Twenty-two years","explanation":"The Wesleyan Methodist Missionary Society was formed in 1813 and began work in Ghana in 1835, a difference of twenty-two years.","syllabus_page":106,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"Which institution is described as playing the single most significant preparatory role for later Methodist work in Ghana?","options":["Philip Quaque's school","The Holy Club","The Fetter Lane Society","The Methodist Conference"],"answer":0,"answer_text":"Philip Quaque's school","explanation":"The syllabus credits the school established by Philip Quaque with a major preparatory role before Methodist missionaries arrived.","syllabus_page":106,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"As headteacher of the Cape Coast school, Joseph Smith introduced:","options":["Bible reading as part of the curriculum","The Love Feast","The Quarterly Meeting","The Watch Night Service"],"answer":0,"answer_text":"Bible reading as part of the curriculum","explanation":"Joseph Smith introduced Bible reading to give pupils an accurate knowledge of Scripture. His insistence that the Bible be read without comment led to disagreement with William deGraft.","syllabus_page":107,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"William deGraft's group at Cape Coast became known as:","options":["The Cape Coast SPCK or Bible Band","The Holy Club","The Moravian Band","The British Conference"],"answer":0,"answer_text":"The Cape Coast SPCK or Bible Band","explanation":"DeGraft and others organized the Society for Promoting Christian Knowledge at Cape Coast, also called the Meeting or Bible Band.","syllabus_page":107,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"The first recorded meeting of the Cape Coast SPCK took place on:","options":["October 1, 1831","January 1, 1835","August 14, 1837","January 3, 1838"],"answer":0,"answer_text":"October 1, 1831","explanation":"The syllabus gives October 1, 1831 as the date of the first meeting recorded for the Cape Coast SPCK.","syllabus_page":107,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"Joseph Rhodes Dunwell died on:","options":["June 24, 1835","January 1, 1835","November 16, 1837","February 20, 1838"],"answer":0,"answer_text":"June 24, 1835","explanation":"Dunwell's ministry in Cape Coast lasted only about six months. He died on June 24, 1835.","syllabus_page":109,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"Which Methodist practice did Dunwell introduce during the Easter weekend of 1835?","options":["The Love Feast","The District Synod","The Watch Night Service","The Covenant Service"],"answer":0,"answer_text":"The Love Feast","explanation":"During Easter 1835 Dunwell introduced the Love Feast, in which those present were allowed to relate their religious experience.","syllabus_page":109,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"Who introduced the Quarterly Meeting into Methodism in Ghana?","options":["George Wrigley","Joseph Rhodes Dunwell","Thomas Birch Freeman","Captain Potter"],"answer":0,"answer_text":"George Wrigley","explanation":"Rev. George Wrigley introduced the Quarterly Meeting, which first met at Cape Coast on August 14, 1837.","syllabus_page":110,"source_type":"Syllabus-derived likely practice question"},{"subject":"Methodist Studies","section":"Methodism in Ghana","q":"Thomas Birch Freeman and his wife arrived at Cape Coast on:","options":["January 3, 1838","September 15, 1836","January 1, 1835","August 14, 1837"],"answer":0,"answer_text":"January 3, 1838","explanation":"Freeman arrived on January 3, 1838. He later became a major figure in the consolidation and expansion of Methodism in Ghana.","syllabus_page":111,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"The phrase 'Third World' is attributed in the syllabus to:","options":["Alfred Sauvy","Abraham Maslow","Emile Durkheim","Robert Marett"],"answer":0,"answer_text":"Alfred Sauvy","explanation":"The syllabus attributes the phrase to the French analyst Alfred Sauvy, who used 'tiers monde' in 1952.","syllabus_page":127,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"Originally, the phrase 'Third World' referred to countries that were:","options":["Neutral in the Cold War","Members of NATO only","Part of the Soviet bloc only","Already industrialized"],"answer":0,"answer_text":"Neutral in the Cold War","explanation":"Sauvy used the expression for neutral countries in the Cold War, with the Western and Soviet blocs understood as the other two 'worlds'.","syllabus_page":127,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"In the North-South economic description used in the syllabus, the 'North' is mainly:","options":["Industrialized and relatively prosperous","Nonindustrial and impoverished","Agricultural only","Without markets"],"answer":0,"answer_text":"Industrialized and relatively prosperous","explanation":"The North is described as industrialized and relatively prosperous, while the South is generally less industrialized and poorer.","syllabus_page":127,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"A commodity is defined in the syllabus as:","options":["Any good, service or intangible item regarded as useful or valuable in a culture","Only a manufactured product","Only food","A government tax"],"answer":0,"answer_text":"Any good, service or intangible item regarded as useful or valuable in a culture","explanation":"The value of goods and services varies across cultures. The syllabus therefore defines commodities broadly as items considered useful or valuable within a culture.","syllabus_page":128,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"The right to use a resource and to deny others the right to use it is described as:","options":["Ownership","Reciprocity","Poverty","Social service"],"answer":0,"answer_text":"Ownership","explanation":"The syllabus discusses ownership in terms of recognized user rights and the ability to permit or deny others access to a resource.","syllabus_page":128,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"According to Sahlins as presented in the syllabus, reciprocity has how many basic forms?","options":["Two","Three","Five","Seven"],"answer":1,"answer_text":"Three","explanation":"The three forms named are generalized reciprocity, balanced reciprocity and negative reciprocity.","syllabus_page":129,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"A market makes it possible for exchange to take the form mainly of:","options":["Buying and selling","Only gift giving","Only taxation","Only borrowing"],"answer":0,"answer_text":"Buying and selling","explanation":"Markets bring sellers and buyers together and allow commodities to be exchanged through buying and selling rather than only through reciprocal gift exchange.","syllabus_page":129,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"The Church's prophetic role in economics includes speaking against:","options":["Unfair distribution, oppression and exploitation","All forms of business","All private ownership","Every form of profit"],"answer":0,"answer_text":"Unfair distribution, oppression and exploitation","explanation":"The syllabus presents the Church as the conscience of society, expected to challenge exploitation, economic injustice and unfair treatment of the weak and poor.","syllabus_page":129,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Development","q":"Which of the following is listed by Jesus in Matthew 25 as a form of social service to the needy?","options":["Providing food for the hungry","Providing care for the sick","Providing clothing for the naked","All of the above"],"answer":3,"answer_text":"All of the above","explanation":"The syllabus lists food, water, shelter, clothing, health care and care for prisoners as examples of Christian social service.","syllabus_page":130,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"PAMSCAD is expanded in the syllabus as:","options":["Programme of Action for the Mitigation of the Social Cost of Adjustment","Programme for African Mission and Social Christian Development","Public Action Movement for Social Care and Development","Programme for Agricultural Management and Social Community Development"],"answer":0,"answer_text":"Programme of Action for the Mitigation of the Social Cost of Adjustment","explanation":"The syllabus names PAMSCAD as the Programme of Action for the Mitigation of the Social Cost of Adjustment.","syllabus_page":131,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"According to the wording used in the syllabus, LEAP stands for:","options":["Life Enhancement and Amelioration Programme","Livelihood Empowerment Against Poverty","Local Economic Assistance Programme","Life Education and Assistance Project"],"answer":0,"answer_text":"Life Enhancement and Amelioration Programme","explanation":"The Part One syllabus gives LEAP as 'Life Enhancement and Amelioration Programme'. This question preserves the wording of the source material.","syllabus_page":131,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"In Maslow's hierarchy, safety and security needs are concerned mainly with:","options":["Assuring basic necessities for the future","Prestige and recognition","Friendship alone","Creative fulfillment"],"answer":0,"answer_text":"Assuring basic necessities for the future","explanation":"Safety and security involve whether basic needs can continue to be met, for example through regular employment, income, job security and retirement provision.","syllabus_page":132,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"Maslow's 'social needs' include:","options":["Friendship, belonging and interaction with others","Food and water","Prestige only","Creative potential only"],"answer":0,"answer_text":"Friendship, belonging and interaction with others","explanation":"Once physiological and safety needs are substantially met, social needs such as friendship, belonging and participation become prominent.","syllabus_page":132,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"Ego, status and esteem needs include the desire for:","options":["Recognition, achievement and appreciation","Food and shelter","Only job security","Only religious worship"],"answer":0,"answer_text":"Recognition, achievement and appreciation","explanation":"The syllabus associates esteem needs with achievement, confidence, independence, prestige, status, recognition, attention and appreciation.","syllabus_page":132,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"According to the syllabus, to live with dignity at least which levels of Maslow's hierarchy should be satisfied?","options":["Only the first level","The first three levels","All five levels without exception","Only self-actualization"],"answer":1,"answer_text":"The first three levels","explanation":"The syllabus states that not everyone reaches self-actualization, but at least the first three levels are needed for a life of dignity.","syllabus_page":132,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"Titus 3:14 is used in the syllabus to encourage Christians to:","options":["Provide for daily necessities and avoid unproductive lives","Withdraw from society","Reject work","Depend entirely on others"],"answer":0,"answer_text":"Provide for daily necessities and avoid unproductive lives","explanation":"Paul's teaching is used to connect good and productive activity with meeting daily necessities and avoiding unproductive living.","syllabus_page":132,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"Paul's example in 2 Thessalonians 3:7-8 emphasizes that he:","options":["Worked night and day so as not to be a burden","Refused all manual labour","Depended on others for food","Taught that poverty was ideal"],"answer":0,"answer_text":"Worked night and day so as not to be a burden","explanation":"The syllabus points to Paul's own labour as an example of responsible Christian life and a refusal to become an unnecessary burden on others.","syllabus_page":132,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"Poverty","q":"Instead of emphasizing a 'Prosperity Gospel', the syllabus calls for the Church to practise a:","options":["Poverty-Alleviation Gospel","Political Gospel","Monastic Gospel","Ritual Gospel"],"answer":0,"answer_text":"Poverty-Alleviation Gospel","explanation":"The syllabus urges the Church to connect the freedom of Christ with practical teaching, advocacy and action that help people move out of poverty.","syllabus_page":133,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"According to the syllabus, work was originally ordained by God as:","options":["A blessing","A punishment only","A sign of unbelief","A temporary human invention"],"answer":0,"answer_text":"A blessing","explanation":"Human beings were intended to work. The syllabus treats work itself as a blessing, while the painful toil connected with the ground is linked to the Fall.","syllabus_page":133,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"Exodus 20:9-10 is used to support the pattern of:","options":["Six days of work and one day of rest","One day of work and six days of rest","No regular work","Only religious labour"],"answer":0,"answer_text":"Six days of work and one day of rest","explanation":"The syllabus points to the six-and-one rhythm to show that both work and rest belong within a responsible biblical pattern.","syllabus_page":134,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"The Book of Proverbs generally:","options":["Praises hard work and condemns laziness","Condemns all wealth","Discourages planning","Teaches dependence on others"],"answer":0,"answer_text":"Praises hard work and condemns laziness","explanation":"The syllabus cites Proverbs to contrast diligence and productive labour with laziness, procrastination and the poverty that often follows them.","syllabus_page":134,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"The idleness of some Thessalonian Christians led them to become:","options":["A burden to the church and meddlers in other people's affairs","More productive citizens","Full-time missionaries","Independent workers"],"answer":0,"answer_text":"A burden to the church and meddlers in other people's affairs","explanation":"The syllabus says their inactivity made them dependent on the church, wasted time that could have helped others and led them into meddling.","syllabus_page":134,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"The syllabus notes that some Greeks regarded ordinary physical labour as:","options":["Degrading work suitable for slaves","The highest form of philosophy","A sacrament","A requirement for citizenship"],"answer":0,"answer_text":"Degrading work suitable for slaves","explanation":"This cultural attitude formed part of the background to Paul's insistence that Christians should work with their own hands and live responsibly.","syllabus_page":135,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"A wrong interpretation of Proverbs 10:22 led some Christians to think that:","options":["Planning and hard work were unnecessary","Work should be done diligently","God's blessing should guide work","Christians should avoid laziness"],"answer":0,"answer_text":"Planning and hard work were unnecessary","explanation":"The syllabus criticizes interpretations that turn God's blessing into an excuse for inactivity, excessive dependence on prayer centres and neglect of productive work.","syllabus_page":135,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"The syllabus presents industry and skill in relation to God's blessing as:","options":["Means through which work may be fruitful","Completely useless","Sinful human effort","A replacement for God"],"answer":0,"answer_text":"Means through which work may be fruitful","explanation":"The point is not that work has no value, but that work and skill should operate under God's blessing and direction rather than being treated as independent of God.","syllabus_page":136,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"Spirituality is described in the syllabus as more than:","options":["Attending services, praying and studying the Bible","Christian character","The work of the Holy Spirit","Moral conduct"],"answer":0,"answer_text":"Attending services, praying and studying the Bible","explanation":"Religious activities matter, but spirituality is also about character and conduct shaped by the indwelling Holy Spirit.","syllabus_page":137,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Work Ethics","q":"Which of the following is listed as a manifestation of laziness?","options":["Procrastination","Lack of initiative","Lack of discipline","All of the above"],"answer":3,"answer_text":"All of the above","explanation":"The syllabus names lack of initiative, procrastination, passivity and lack of discipline as habits through which laziness appears.","syllabus_page":138,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"Genesis 1:26-31 is used in the syllabus to show that humanity was created to:","options":["Exercise responsible rule over creation","Destroy creation without limit","Avoid involvement with nature","Leave the earth unmanaged"],"answer":0,"answer_text":"Exercise responsible rule over creation","explanation":"Being made in God's image is linked with responsibility for creation. Human rule is treated as accountable stewardship, not permission for careless destruction.","syllabus_page":139,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"Which of the following is listed as a result of environmental degradation?","options":["Global warming","Drying up of water bodies","Air and noise pollution","All of the above"],"answer":3,"answer_text":"All of the above","explanation":"The syllabus connects destructive practices with climatic changes, global warming, drying water bodies, pollution and conversion of forests into grasslands.","syllabus_page":140,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"Why does the syllabus emphasize a 'culture of maintenance'?","options":["Because possessing something also brings responsibility to care for it","Because maintenance replaces work","Because only government must maintain resources","Because creation has no future value"],"answer":0,"answer_text":"Because possessing something also brings responsibility to care for it","explanation":"The syllabus links working with maintaining what has been entrusted to us. Stewardship involves preserving resources so future generations can also benefit.","syllabus_page":141,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"According to the syllabus, Christians have a particularly strong reason to care for the environment because:","options":["They believe in a Creator-God who entrusted creation to humanity","They alone use natural resources","Environmental issues are only church matters","The Bible forbids agriculture"],"answer":0,"answer_text":"They believe in a Creator-God who entrusted creation to humanity","explanation":"The argument is theological: creation belongs to God, and humans are entrusted with responsibility for it. Christian belief therefore strengthens the duty of environmental care.","syllabus_page":141,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"Leviticus 25:23 is used to support the idea that:","options":["The land belongs ultimately to God and humans are stewards or tenants","Land may never be farmed","Only priests may own land","Land has no spiritual significance"],"answer":0,"answer_text":"The land belongs ultimately to God and humans are stewards or tenants","explanation":"The syllabus uses the statement that 'the land is mine' to emphasize stewardship and the need to preserve and restore the land's fertility.","syllabus_page":143,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"One cause of flooding in urban centres identified in the syllabus is:","options":["Building in waterways","Planting trees","Desilting drains","Harvesting rainwater"],"answer":0,"answer_text":"Building in waterways","explanation":"Buildings in waterways obstruct the natural flow of water and contribute to flooding and destruction.","syllabus_page":145,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"Human causes of bushfires are grouped in the syllabus as:","options":["Malicious, careless and accidental acts","Economic, political and religious acts","Natural, spiritual and ceremonial acts","Agricultural acts only"],"answer":0,"answer_text":"Malicious, careless and accidental acts","explanation":"The syllabus distinguishes deliberately set fires, careless actions and accidental fires. Lightning is discussed separately as a natural cause.","syllabus_page":146,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"Which of the following can be destroyed or harmed by bushfires?","options":["Wildlife and vegetation","Homes and public property","Human life","All of the above"],"answer":3,"answer_text":"All of the above","explanation":"The syllabus describes damage to fauna, flora, habitats, people, homes, bridges, power lines and air quality.","syllabus_page":146,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and the Environment","q":"The syllabus regards apathy when God's creation is threatened by bushfires as:","options":["A responsible response","Morally unacceptable for Christians","A private matter only","The duty of government alone"],"answer":1,"answer_text":"Morally unacceptable for Christians","explanation":"Christians are called to become part of the solution through prevention, stewardship, support for fire control and practical involvement rather than indifference.","syllabus_page":147,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"Which of the following is included among the broad characteristics of religion in the syllabus?","options":["Belief in supernatural beings or power","Symbolic expression of feelings","Rituals intended to relate to supernatural beings or powers","All of the above"],"answer":3,"answer_text":"All of the above","explanation":"The syllabus describes religion through supernatural belief, symbolic expression and ritual practices that give meaning and shape relationships with the supernatural.","syllabus_page":148,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"Tylor's theory of animism is presented as helping people explain experiences such as:","options":["Dreams, sleep and hallucinations","Only economic exchange","Only political conflict","Only language development"],"answer":0,"answer_text":"Dreams, sleep and hallucinations","explanation":"Tylor's approach linked religion to belief in supernatural beings and used it to explain puzzling experiences such as dreams, sleep, unconsciousness and hallucinations.","syllabus_page":148,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"Marett argued that the concept of 'mana' arose primarily from:","options":["Emotion","Economic need","Political power","Written law"],"answer":0,"answer_text":"Emotion","explanation":"The syllabus contrasts Marett with Tylor by saying Marett regarded mana as an ancient and widespread religious idea arising from emotion rather than intellect.","syllabus_page":148,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"The term 'taboo' is linked in the syllabus with the idea of something that is:","options":["Forbidden and sacred","Ordinary and secular","Commercial and public","Temporary and meaningless"],"answer":0,"answer_text":"Forbidden and sacred","explanation":"The word is traced to Polynesian 'tapu' or 'tabu', carrying the senses of both forbidden and sacred, especially in relation to things charged with spiritual power.","syllabus_page":149,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"Emile Durkheim emphasized religion as a system of beliefs and practices concerning:","options":["Sacred things","Markets","Political parties","Only private opinions"],"answer":0,"answer_text":"Sacred things","explanation":"Durkheim focused on sacred things that evoke awe, respect or reverence and on religion's role in forming and stabilizing community life.","syllabus_page":149,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"A society is described in the syllabus as people connected by:","options":["Communication, common customs and traditions, and institutions","Biology alone","Religion alone","Geography alone"],"answer":0,"answer_text":"Communication, common customs and traditions, and institutions","explanation":"The syllabus describes societies as groups that see themselves as distinct and are connected through communication, shared customs and institutions such as politics, law and economics.","syllabus_page":149,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"Shared culture contributes to a society by giving members:","options":["A sense of common identity","Exactly identical knowledge","No rules for behaviour","Freedom from tradition"],"answer":0,"answer_text":"A sense of common identity","explanation":"Culture provides shared beliefs, feelings and rules for living that help members understand themselves as a people with a common identity.","syllabus_page":149,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"The syllabus says that culture is:","options":["Fixed and unchanging","Capable of diversity and change within the same society","Identical for every member","Only inherited biologically"],"answer":1,"answer_text":"Capable of diversity and change within the same society","explanation":"Culture is learned, shared and transmitted, but it is not fixed. Different groups within one society may possess distinctive cultural knowledge and practices.","syllabus_page":150,"source_type":"Syllabus-derived likely practice question"},{"subject":"Church & Society","section":"The Christian and Culture","q":"Clothing and language are used in the syllabus to illustrate that culture:","options":["Communicates symbolic meaning and identity","Has no connection with identity","Is limited to religion","Cannot change"],"answer":0,"answer_text":"Communicates symbolic meaning and identity","explanation":"Clothing can communicate shared symbolic meanings, while language expresses community identity and helps people understand who they are as a group.","syllabus_page":150,"source_type":"Syllabus-derived likely practice question"}];
const LETTERS=["A","B","C","D","E","F","G"];

let set=[], i=0, score=0, scored=0, states=[], quizStarted=false;

const $=id=>document.getElementById(id);
const subject=$("subject"), topic=$("topic"), order=$("order"),
badges=$("badges"), prog=$("prog"), scoreEl=$("score"), bar=$("bar"),
meta=$("meta"), questionEl=$("question"), answers=$("answers"),
feedback=$("feedback"), prev=$("prev"), next=$("next"), reset=$("reset"),
quiz=$("quiz"), finish=$("finish"), final=$("final"),
questionNav=$("questionNav"), navSummary=$("navSummary"),
toggleNav=$("toggleNav"), navWrap=$("navWrap");

function track(name,params={}){
  if(typeof gtag==="function") gtag("event",name,params);
}

function context(){
  return {
    quiz_part:"Part One Syllabus Practice",
    practice_subject:subject.value,
    practice_topic:topic.value,
    question_order:order.value,
    total_questions:set.length
  };
}

function esc(s){
  return String(s ?? "").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
}

function shuffle(a){
  const b=a.slice();
  for(let x=b.length-1;x>0;x--){
    const j=Math.floor(Math.random()*(x+1));
    [b[x],b[j]]=[b[j],b[x]];
  }
  return b;
}

function initSubjects(){
  const subjects=[...new Set(ALL_QUESTIONS.map(x=>x.subject))];
  subject.innerHTML=`<option value="ALL">All subjects (${ALL_QUESTIONS.length})</option>`;
  for(const s of subjects){
    const n=ALL_QUESTIONS.filter(x=>x.subject===s).length;
    subject.insertAdjacentHTML("beforeend",`<option value="${esc(s)}">${esc(s)} (${n})</option>`);
  }
  refreshTopics();
}

function refreshTopics(){
  const base=subject.value==="ALL"
    ?ALL_QUESTIONS
    :ALL_QUESTIONS.filter(x=>x.subject===subject.value);

  const topics=[...new Set(base.map(x=>x.section))];
  topic.innerHTML=`<option value="ALL">All topics (${base.length})</option>`;

  for(const t of topics){
    const n=base.filter(x=>x.section===t).length;
    topic.insertAdjacentHTML("beforeend",`<option value="${esc(t)}">${esc(t)} (${n})</option>`);
  }

  build();
}

function build(){
  let base=ALL_QUESTIONS.filter(x=>
    (subject.value==="ALL" || x.subject===subject.value) &&
    (topic.value==="ALL" || x.section===topic.value)
  );

  set=order.value==="shuffle" ? shuffle(base) : base.slice();

  i=0; score=0; scored=0; states=set.map(()=>null); quizStarted=false;
  quiz.hidden=false; finish.hidden=true;

  badges.innerHTML=
    `<span class="badge">${set.length} questions</span>`+
    `<span class="badge">Syllabus practice</span>`;

  renderNav();
  render();
}

function renderNav(){
  questionNav.innerHTML="";
  const frag=document.createDocumentFragment();

  set.forEach((x,idx)=>{
    const b=document.createElement("button");
    b.type="button";
    b.className="nav-question";
    b.textContent=idx+1;
    const navState =
      states[idx]?.ok===true ? "Correct" :
      states[idx]?.ok===false ? "Wrong" :
      "Not answered";

    b.title=`Question ${idx+1} • ${x.subject} • ${x.section} • ${navState}`;
    b.addEventListener("click",()=>{
      const from=i+1; i=idx;
      track("practice_question_navigated",{
        ...context(),
        from_question:from,
        to_question:idx+1,
        target_result:
          states[idx]?.ok===true ? "correct" :
          states[idx]?.ok===false ? "incorrect" :
          "unanswered"
      });
      render();
    });
    frag.appendChild(b);
  });

  questionNav.appendChild(frag);
  updateNav();
}

function updateNav(){
  const buttons=questionNav.querySelectorAll(".nav-question");
  buttons.forEach((b,idx)=>{
    b.className="nav-question";
    if(idx===i) b.classList.add("current");
    else if(states[idx]?.ok===true) b.classList.add("correct");
    else if(states[idx]?.ok===false) b.classList.add("wrong");
  });
  navSummary.textContent=`${states.filter(Boolean).length} of ${set.length} answered`;
}

function render(){
  if(!set.length){
    prog.textContent="Question 0 of 0";
    scoreEl.textContent="Score: 0 / 0";
    questionEl.textContent="No questions in this selection.";
    answers.innerHTML="";
    feedback.hidden=true;
    next.disabled=true;
    prev.disabled=true;
    return;
  }

  const x=set[i], st=states[i];

  prog.textContent=`Question ${i+1} of ${set.length}`;
  scoreEl.textContent=`Score: ${score} / ${scored}`;
  bar.style.width=`${((i+1)/set.length)*100}%`;
  meta.textContent=`${x.subject} • ${x.section} • Syllabus Practice`;
  questionEl.textContent=x.q;

  answers.innerHTML="";
  feedback.hidden=true;
  feedback.innerHTML="";

  x.options.forEach((opt,j)=>{
    const b=document.createElement("button");
    b.type="button";
    b.className="answer";
    b.textContent=`${LETTERS[j]}. ${opt}`;

    if(st){
      b.disabled=true;
      if(j===x.answer) b.classList.add("correct");
      if(j===st.choice && j!==x.answer) b.classList.add("wrong");
    }

    b.addEventListener("click",()=>choose(j));
    answers.appendChild(b);
  });

  if(st) showFeedback(x,st);

  prev.disabled=i===0;
  next.disabled=!st;
  next.textContent=i===set.length-1 ? "Finish" : "Next";
  updateNav();
}

function choose(choice){
  if(states[i]) return;

  const x=set[i];
  if(!quizStarted){
    quizStarted=true;
    track("practice_quiz_started",context());
  }

  const ok=choice===x.answer;
  states[i]={choice,ok};
  scored++;
  if(ok) score++;

  track("practice_question_answered",{
    ...context(),
    question_number:i+1,
    question_subject:x.subject,
    question_topic:x.section,
    answer_result:ok ? "correct" : "incorrect"
  });

  render();
}

function showFeedback(x,st){
  feedback.hidden=false;

  const ans=x.options[x.answer];
  const head=st.ok
    ?`<strong class="good">✓ Correct.</strong>`
    :`<strong class="bad">✗ Incorrect.</strong>`;

  feedback.innerHTML=
    `${head}<br>`+
    `<strong>Verified answer: ${LETTERS[x.answer]}. ${esc(ans)}</strong>`+
    `<div class="teaching"><strong>Why this answer is correct:</strong>`+
    `<p>${esc(x.explanation)}</p></div>`+
    `<span class="ref">Part One syllabus, p. ${x.syllabus_page}</span>`;
}

reset.addEventListener("click",()=>{
  const x=set[i], st=states[i];

  if(!st) return;

  if(st.ok){
    score=Math.max(0,score-1);
  }
  scored=Math.max(0,scored-1);

  track("practice_question_reset",{
    ...context(),
    question_number:i+1,
    question_subject:x.subject,
    question_topic:x.section,
    previous_result:st.ok ? "correct" : "incorrect"
  });

  states[i]=null;
  render();

  const firstAnswer=answers.querySelector(".answer");
  if(firstAnswer){
    firstAnswer.focus();
  }
});

prev.addEventListener("click",()=>{
  if(i>0){i--;render();}
});

next.addEventListener("click",()=>{
  if(i<set.length-1){
    i++; render();
  } else {
    const pct=scored ? Number(((score/scored)*100).toFixed(1)) : 0;
    track("practice_quiz_completed",{...context(),quiz_score:score,scored_questions:scored,quiz_percentage:pct});
    quiz.hidden=true;
    finish.hidden=false;
    final.textContent=`You scored ${score} out of ${scored} questions (${pct}%).`;
  }
});

subject.addEventListener("change",()=>{
  track("practice_subject_selected",{selected_subject:subject.value});
  refreshTopics();
});

topic.addEventListener("change",()=>{
  track("practice_topic_selected",{selected_subject:subject.value,selected_topic:topic.value});
  build();
});

order.addEventListener("change",()=>{
  track("practice_order_changed",{selected_order:order.value});
  build();
});

toggleNav.addEventListener("click",()=>{
  navWrap.hidden=!navWrap.hidden;
  toggleNav.textContent=navWrap.hidden ? "Show" : "Hide";
});

initSubjects();